/**
 * GenyCaster 3D identity — real physically based glass and generated studio IBL.
 * Render on demand: no perpetually running animation loop.
 *
 * Three.js is vendored locally, version-pinned and licensed under MIT.
 * GLB models are generated by generate_assets.py and shared with Qt Quick 3D.
 */
import * as THREE from "./three.module.js";

const surface = document.querySelector("#demo");
const canvas = document.querySelector("#scene");
const status = document.querySelector("#status");
const motionButton = document.querySelector("#motion");
const reducedQuery = window.matchMedia("(prefers-reduced-motion: reduce)");
let dark = true;
let reducedMotion = reducedQuery.matches;
let renderer, camera, scene, group, environment, environmentTarget, background;
let objects = [];
let currentToken = 0;
let pointer = new THREE.Vector2(0, 0);
let targetRotation = new THREE.Vector2(0, 0);
let raf = 0;
let pulseStart = 0;
let allowHover = true;

const CSS = {
  dark: {sideTop:"#071521", sideBottom:"#091927",ink:"#e8fbff",ambient:"#33b8d2"},
  light:{sideTop:"#f5fbfe", sideBottom:"#e7f3fa",ink:"#1d3a4c",ambient:"#46b5d1"}
};

function clearPrevious() {
    for (const mesh of objects) {
        group.remove(mesh);
        mesh.geometry.dispose();
        mesh.material.dispose();
    }
    objects = [];
    if (environmentTarget) environmentTarget.dispose();
    environmentTarget = null;
    if (environment) environment.dispose();
    environment = null;
    if (background) {
        scene.remove(background);
        background.material.map.dispose();
        background.material.dispose();
        background.geometry.dispose();
        background = null;
    }
}

function getGeometry(raw, gltf, primitive) {
    function arrayFor(accessorId, kind, count) {
        const a = gltf.accessors[accessorId], view=gltf.bufferViews[a.bufferView];
        const itemBytes=a.componentType===5125 || a.componentType===5126?4:2;
        const begin=raw.byteOffset + (view.byteOffset||0) + (a.byteOffset||0);
        const byteSize=a.count*count*itemBytes;
        const bytes=raw.buffer.slice(begin,begin+byteSize);
        if (a.componentType===5126) return new Float32Array(bytes);
        if (a.componentType===5125) return new Uint32Array(bytes);
        throw new Error("Unsupported GLB accessor "+a.componentType);
    }
    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute("position",new THREE.BufferAttribute(arrayFor(primitive.attributes.POSITION,"f",3),3));
    geometry.setAttribute("normal",new THREE.BufferAttribute(arrayFor(primitive.attributes.NORMAL,"f",3),3));
    geometry.setIndex(new THREE.BufferAttribute(arrayFor(primitive.indices,"i",1),1));
    geometry.computeBoundingSphere();
    return geometry;
}
function parseGLB(data) {
    const dv = new DataView(data);
    if (dv.getUint32(0,true)!==0x46546c67 || dv.getUint32(4,true)!==2) {
        throw new Error("Expected binary glTF 2.0");
    }
    if (dv.getUint32(8,true)!==data.byteLength) throw new Error("Incomplete GLB transfer");
    const jlen=dv.getUint32(12,true);
    const gltf=JSON.parse(new TextDecoder().decode(new Uint8Array(data,20,jlen)));
    const offset=20+jlen, len=dv.getUint32(offset,true);
    if (dv.getUint32(offset+4,true)!==0x004e4942) throw new Error("GLB geometry missing");
    return {gltf,raw:new Uint8Array(data,offset+8,len)};
}

function physicalMaterial(modelName,colors) {
    const light = !dark;
    if (modelName.startsWith("ReflectiveEdge_") || modelName.startsWith("UpperBevel_")) {
        const warm = modelName.endsWith("_1");
        return new THREE.MeshBasicMaterial({
            color: warm ? (light? "#B98B4C" : "#FFE0A3") :
                (light ? "#24B8C5" : "#7DF6E5"),
            transparent:true, opacity:light?0.62:0.76,
            blending:THREE.AdditiveBlending, depthWrite:false, side:THREE.DoubleSide,
            toneMapped:false
        });
    }
    if (modelName==="FloatingGlassOrb") {
        return new THREE.MeshPhysicalMaterial({
            color:light?"#D4FFFF":"#9BF9EC",
            roughness:0.03,metalness:0, transmission:0.93,
            thickness:4,ior:1.47,clearcoat:1,clearcoatRoughness:0.035,
            attenuationColor:new THREE.Color("#70CFCF"),
            attenuationDistance:300,envMapIntensity:2.4
        });
    }
    if (modelName==="SculpturalRibbon") {
        return new THREE.MeshPhysicalMaterial({
            color:light?"#69D4DC":"#5FD8D9",roughness:.07,
            metalness:0.08,transmission:.62,thickness:2.4,
            ior:1.44,clearcoat:1,clearcoatRoughness:.04,
            attenuationColor:new THREE.Color(light?"#6FC7CF":"#38ABB1"),
            attenuationDistance:260,
            envMapIntensity:light?2.1:2.8,
            side:THREE.DoubleSide
        });
    }
    const idx = modelName.endsWith("Front")?0:modelName.endsWith("Middle")?1:2;
    const tint = (light?["#B3F0F4","#95E3EC","#B0DFF1"]:["#88DEE9","#83E5E8","#A2C7ED"])[idx];
    // A true 3D glass shell with an edge-weighted shader. Multi-layer
    // screen-space transmission produces micro-triangle interference on
    // ANGLE/SwiftShader when three curved shells overlap. Use stable single
    // pass thin-film Fresnel here; physically refractive PBR remains on the
    // sphere and sculptural tube. Both variants are fully GPU shaded.
    if (dark || new URLSearchParams(location.search).has("pbr")) {
        return new THREE.MeshPhysicalMaterial({
            color:tint,metalness:0.015,roughness:0.045,
            transmission:0.88,thickness:4.5,ior:1.46,
            clearcoat:1,clearcoatRoughness:0.035,
            envMapIntensity:dark?3.3:2.7,
            attenuationColor:new THREE.Color(light?"#84D8DB":"#4FCEDE"),
            attenuationDistance:300,
            side:THREE.DoubleSide
        });
    }
    const film = new THREE.ShaderMaterial({
        uniforms: {
            uTint:{value:new THREE.Color(tint)},
            uDark:{value:dark?1:0},
            uWarm:{value:new THREE.Color(light?"#E4B777":"#FFCC82")}
        },
        vertexShader:`
            varying vec3 vNormal;
            varying vec3 vView;
            varying vec3 vPosition;
            void main() {
                vec4 view = modelViewMatrix * vec4(position,1.0);
                vView = normalize(-view.xyz);
                vNormal = normalize(normalMatrix * normal);
                vPosition = position;
                gl_Position = projectionMatrix * view;
            }`,
        fragmentShader:`
            precision highp float;
            uniform vec3 uTint;
            uniform vec3 uWarm;
            uniform float uDark;
            varying vec3 vNormal;
            varying vec3 vView;
            varying vec3 vPosition;
            void main() {
                vec3 n=normalize(vNormal);
                vec3 view=normalize(vView);
                float edge=pow(1.0-abs(dot(n,view)),2.5);
                vec3 l1=normalize(vec3(-0.44,0.75,0.85));
                vec3 l2=normalize(vec3(0.83,0.15,0.68));
                float cool=pow(max(dot(reflect(-l1,n),view),0.0),28.0);
                float warm=pow(max(dot(reflect(-l2,n),view),0.0),50.0);
                float vertical=0.5+0.5*sin(vPosition.y*0.0031+1.1);
                vec3 color=uTint*(0.54+vertical*0.21)+
                           vec3(0.47,1.0,0.93)*cool*0.55+
                           uWarm*warm*0.33+vec3(0.37,0.94,1.0)*edge*0.3;
                float alpha=(uDark>0.5?0.24:0.19)+edge*0.23+cool*0.12+warm*0.06;
                gl_FragColor=vec4(color,clamp(alpha,0.0,0.68));
            }`,
        transparent:true,depthWrite:false,side:THREE.DoubleSide
    });
    film.forceSinglePass = true;
    return film;
}

function makeBackgroundTexture() {
    const c=document.createElement("canvas");
    c.width=768;c.height=1400;
    const g=c.getContext("2d");
    let grad=g.createLinearGradient(0,0,0,c.height);
    if (dark) {
        grad.addColorStop(0,"#071521");grad.addColorStop(.40,"#103146");
        grad.addColorStop(.81,"#153B4B");grad.addColorStop(1,"#071826");
    } else {
        grad.addColorStop(0,"#F5FAFD");grad.addColorStop(.46,"#DCEFF4");
        grad.addColorStop(.79,"#DAF1F4");grad.addColorStop(1,"#F6FAFC");
    }
    g.fillStyle=grad;g.fillRect(0,0,c.width,c.height);
    function glow(x,y,rx,ry,color,opacity){
        g.save();g.translate(x,y);g.scale(rx,ry);
        const radial=g.createRadialGradient(0,0,0,0,0,1);
        radial.addColorStop(0,color);
        radial.addColorStop(1,"transparent");
        g.globalAlpha=opacity;g.fillStyle=radial;
        g.beginPath();g.arc(0,0,1,0,Math.PI*2);g.fill();g.restore();
    }
    glow(490,630,460,600,"#37E9DC",dark?.24:.21);
    glow(730,430,290,560,"#F8C989",dark?.15:.14);
    glow(110,880,450,450,"#2E98CB",dark?.16:.12);
    // Architectural vertical light echoes the reference without dominating.
    for(let i=0;i<24;i++){
        const xx=i*c.width/23;
        g.fillStyle=dark?"rgba(126,232,224,.028)":"rgba(54,141,163,.028)";
        g.fillRect(xx,0,1.0,c.height);
    }
    const tex=new THREE.CanvasTexture(c);
    tex.colorSpace=THREE.SRGBColorSpace;
    return tex;
}
function makeEnvironment() {
    const texturePath=dark?"studio-dark.png":"studio-light.png";
    return new Promise((resolve,reject)=>{
        new THREE.TextureLoader().load("./assets/"+texturePath,tex=>{
            tex.mapping=THREE.EquirectangularReflectionMapping;
            tex.colorSpace=THREE.SRGBColorSpace;
            resolve(tex);
        },undefined,reject);
    });
}
async function init() {
    if (!document.createElement("canvas").getContext("webgl2")) {
        throw new Error("WebGL 2 is not available on this device");
    }
    renderer=new THREE.WebGLRenderer({
        canvas,antialias:true,alpha:true,powerPreference:"high-performance",
        preserveDrawingBuffer:false
    });
    renderer.setPixelRatio(Math.min(1.8,window.devicePixelRatio||1));
    renderer.outputColorSpace=THREE.SRGBColorSpace;
    renderer.toneMapping=THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure=1.40;
    scene=new THREE.Scene();
    group=new THREE.Group();
    scene.add(group);
    camera=new THREE.PerspectiveCamera(43,1,.1,5000);
    camera.position.set(0,3,950);
    camera.lookAt(0,0,0);
    const ambient=new THREE.HemisphereLight("#E5FCFF","#154151",dark?.85:1.15);
    scene.add(ambient);
    const key=new THREE.DirectionalLight("#E6FFFF",dark?4.8:3.5);
    key.position.set(-350,550,780);scene.add(key);
    const warm=new THREE.DirectionalLight("#FFD8A1",dark?2.9:2.0);
    warm.position.set(480,100,400);scene.add(warm);
    const rim=new THREE.PointLight("#4BDDEA",dark?20000:14500,1200,1.6);
    rim.position.set(-270,-140,380);scene.add(rim);
    canvas.addEventListener("webglcontextlost",e=>{
        e.preventDefault();cancelAnimationFrame(raf);
        status.textContent="GPU context was lost. Reload this preview.";
    },{passive:false});
    resize();
    await switchTheme(true);
}
function resize(){
    if(!renderer)return;
    const w=Math.max(1,canvas.clientWidth),h=Math.max(1,canvas.clientHeight);
    renderer.setSize(w,h,false);
    camera.aspect=w/h;camera.updateProjectionMatrix();
    invalidate();
}
async function switchTheme(value) {
    dark=value;
    const token=++currentToken;
    surface.classList.toggle("dark",dark);
    surface.classList.toggle("light",!dark);
    document.getElementById("dark").setAttribute("aria-pressed",String(dark));
    document.getElementById("light").setAttribute("aria-pressed",String(!dark));
    status.classList.remove("err");
    status.textContent="Preparing "+(dark?"dark":"light")+" glass materials…";
    try {
        const file=dark?"brand-dark.glb":"brand-light.glb";
        const [res,studio] = await Promise.all([
            fetch("./assets/"+file,{cache:"force-cache"}),
            makeEnvironment()
        ]);
        if (!res.ok) throw Error(file+" HTTP "+res.status);
        const {gltf,raw}=parseGLB(await res.arrayBuffer());
        if(token!==currentToken){studio.dispose();return;}
        clearPrevious();
        environment=studio;
        const pmrem=new THREE.PMREMGenerator(renderer);
        environmentTarget=pmrem.fromEquirectangular(studio);
        pmrem.dispose();
        scene.environment=environmentTarget.texture;
        const bgtex=makeBackgroundTexture();
        background=new THREE.Mesh(
            new THREE.PlaneGeometry(2200,3000),
            new THREE.MeshBasicMaterial({map:bgtex,depthWrite:false,depthTest:true,toneMapped:false})
        );
        background.position.set(0,0,-490);
        background.renderOrder=-5;
        scene.add(background);
        for (const meshDef of gltf.meshes) {
            const prim=meshDef.primitives[0];
            const mesh=new THREE.Mesh(getGeometry(raw,gltf,prim),physicalMaterial(meshDef.name));
            mesh.name=meshDef.name;
            mesh.renderOrder=mesh.name.startsWith("ReflectiveEdge") || mesh.name.startsWith("UpperBevel") ? 20 : 1;
            mesh.frustumCulled=false;
            group.add(mesh);
            objects.push(mesh);
        }
        renderer.toneMappingExposure=dark?1.56:1.29;
        invalidate();
        status.textContent="WebGL 2 · reflective GPU glass · "+objects.length+" 3D meshes · hover to inspect";
    }catch(error){
        console.error("[Brand3D]",error);
        status.classList.add("err");
        status.textContent="GPU preview error: "+error.message;
    }
}
function invalidate(){
    if (!raf)raf=requestAnimationFrame(frame);
}
function frame(t){
    raf=0;
    if(!renderer)return;
    if (!reducedMotion && allowHover) {
        group.rotation.y+=(targetRotation.x-group.rotation.y)*.14;
        group.rotation.x+=(targetRotation.y-group.rotation.x)*.14;
    }else {
        group.rotation.y=0;group.rotation.x=0;
    }
    let scale=1;
    if(pulseStart && !reducedMotion){
        let u=Math.min(1,(t-pulseStart)/750);
        scale+=0.018*Math.sin(Math.PI*u);
        if(u>=1)pulseStart=0;
    }
    group.scale.setScalar(scale);
    renderer.render(scene,camera);
    const delta=Math.max(
        Math.abs(targetRotation.x-group.rotation.y),
        Math.abs(targetRotation.y-group.rotation.x)
    );
    if((delta>.00025&&!reducedMotion)||pulseStart) invalidate();
}
document.getElementById("dark").addEventListener("click",()=>switchTheme(true));
document.getElementById("light").addEventListener("click",()=>switchTheme(false));
motionButton.setAttribute("aria-pressed",String(reducedMotion));
motionButton.addEventListener("click",()=>{
    reducedMotion=!reducedMotion;
    motionButton.setAttribute("aria-pressed",String(reducedMotion));
    if(reducedMotion)targetRotation.set(0,0);
    invalidate();
});
reducedQuery.addEventListener?.("change",e=>{
    reducedMotion=e.matches;motionButton.setAttribute("aria-pressed",String(reducedMotion));
    if(reducedMotion)targetRotation.set(0,0);
    invalidate();
});
canvas.addEventListener("pointermove",e=>{
    if(reducedMotion)return;
    const r=canvas.getBoundingClientRect();
    targetRotation.set(
        ((e.clientX-r.left)/r.width-.5)*.20,
        ((e.clientY-r.top)/r.height-.5)*.115
    );
    invalidate();
});
canvas.addEventListener("pointerleave",()=>{targetRotation.set(0,0);invalidate()});
canvas.addEventListener("click",()=>{
    if(reducedMotion)return;
    pulseStart=performance.now();
    invalidate();
});
window.addEventListener("resize",resize);
try {
    await init();
} catch(error) {
    console.error("[Brand3D]",error);
    status.classList.add("err");
    status.textContent="Unable to initialize GPU: "+error.message;
}
